-- Test helper: the selected version's installed generated view. `scripts/test.sh`
-- prepares the scoped corpus with the real producer; this helper hydrates that
-- snapshot with the production archive owner into one resident store and answers
-- the reader a boot installs. A suite that drives production composition
-- directly therefore reads the same bytes an epoch installs, never a loose
-- generated file: the persistent private test root may carry output from older
-- builds, and the compatibility contract says such files are ignored.
--
-- The view is created once per process and version, is read-only, and never
-- writes into the shared prepared root. A suite whose generated bytes include
-- its own synthetic payloads builds an overlay or a fixture-only view instead:
-- both are ordinary resident stores, so reading them goes through the same
-- reader shape and identity rules as an installed epoch.

local Assert = require("tests.support.Assert")
local CacheArchive = require("romdump.src.build.CacheArchive")
local CacheFs = require("libs.storage.src.CacheFs")
local ResidentCache = require("libs.storage.src.ResidentCache")

local GeneratedCacheFixture = {}

---@class GeneratedCacheFixture.View
---@field versionId string
---@field generationId string
---@field sourceId string
---@field candidate table<string, unknown> hydrated snapshot
---@field store ResidentCache installed byte store
---@field reader CacheFs installed generated reader

---@type table<string, GeneratedCacheFixture.View>
local views = {}

---@param versionId string
---@return GeneratedCacheFixture.View
local function build(versionId)
  local candidate, failure = CacheArchive.open(versionId)
  Assert.isTrue(
    candidate ~= nil,
    "the runner-prepared snapshot must hydrate for "
      .. versionId
      .. ": "
      .. tostring(type(failure) == "table" and failure.message or failure)
  )
  local hydrated = candidate --[[@as table<string, unknown>]]
  local identity = hydrated.identity --[[@as table<string, unknown> ]]
  Assert.isTrue(
    type(identity) == "table" and type(identity.generationId) == "string",
    "a hydrated snapshot carries its generation identity"
  )
  local generationId = identity.generationId --[[@as string]]
  local sourceId = "base:" .. generationId
  local store = ResidentCache.new(versionId, sourceId)
  local entries = {}
  for position, entry in ipairs(hydrated.entries --[[@as table[] ]]) do
    entries[position] = {
      path = entry.path,
      data = entry.data,
      size = entry.size,
      sourceId = sourceId,
      contentId = generationId .. "\0" .. entry.path,
    }
  end
  store:commit(store:prepare(entries))
  return {
    versionId = versionId,
    generationId = generationId,
    sourceId = sourceId,
    candidate = hydrated,
    store = store,
    reader = CacheFs.fromStore(store),
  }
end

-- One resident entry per logical fixture payload. A fixture payload carries its
-- own content identity, so replacing the bytes at a path is a new identity
-- rather than a silent overwrite of an already-decoded payload.
---@param path string
---@param bytes string|love.Data
---@param sourceId string
---@param contentId string
---@return ResidentCache.BatchEntry
local function entry(path, bytes, sourceId, contentId)
  assert(type(path) == "string" and path ~= "", "a fixture payload needs its logical path")
  local text = type(bytes) == "userdata" and bytes:getString() or bytes
  assert(type(text) == "string", "fixture payload must be bytes: " .. path)
  return {
    path = path,
    data = assert(love.data.newByteData(text), "fixture payload must be readable bytes: " .. path),
    size = #text,
    sourceId = sourceId,
    contentId = contentId,
  }
end

-- The prepared snapshot's entries unchanged, as one batch: sharing the
-- committed buffers keeps an overlay cheap.
---@param base GeneratedCacheFixture.View
---@return ResidentCache.BatchEntry[]
local function baseEntries(base)
  local entries = {}
  for position, committed in ipairs(base.candidate.entries --[[@as table[] ]]) do
    entries[position] = {
      path = committed.path,
      data = committed.data,
      size = committed.size,
      sourceId = base.sourceId,
      contentId = base.generationId .. "\0" .. committed.path,
    }
  end
  return entries
end

---@class GeneratedCacheFixture.ResidentView
---@field versionId string
---@field store ResidentCache private fixture byte store
---@field reader CacheFs fixture generated reader
---@field serialize integer? monotone fixture revision for replaced payloads

---@param versionId string
---@param sourceId string
---@param batch ResidentCache.BatchEntry[]
---@return GeneratedCacheFixture.ResidentView
local function residentView(versionId, sourceId, batch)
  local store = ResidentCache.new(versionId, sourceId)
  if #batch > 0 then
    store:commit(store:prepare(batch))
  end
  return { versionId = versionId, store = store, reader = CacheFs.fromStore(store) }
end

-- A resident view over the prepared snapshot with fixture payloads layered on
-- top: the same committed bytes plus the suite's own logical payloads. A suite
-- that needs generated bytes the shared preparation does not carry (or that
-- contradicts them) reads its own overlay instead of writing into the shared
-- prepared root.
---@param versionId string
---@param assets table<string, string|love.Data> fixture payloads by logical generated path
---@return GeneratedCacheFixture.ResidentView
function GeneratedCacheFixture.overlay(versionId, assets)
  local base = GeneratedCacheFixture.view(versionId)
  local paths = {}
  for path in pairs(assets) do
    paths[#paths + 1] = path
  end
  table.sort(paths)
  local replaced = {}
  for _, path in ipairs(paths) do
    replaced[path] = true
  end
  -- A fixture payload at an already committed path replaces it: the batch
  -- carries one entry per path, exactly like an installation.
  local batch = {}
  for _, committed in ipairs(baseEntries(base)) do
    if not replaced[committed.path] then
      batch[#batch + 1] = committed
    end
  end
  for _, path in ipairs(paths) do
    batch[#batch + 1] = entry(path, assets[path], base.sourceId, base.generationId .. "\0fixture\0" .. path)
  end
  return residentView(versionId, base.sourceId, batch)
end

-- A resident view over fixture payloads only, for a suite whose generated bytes
-- are synthetic and never come from the prepared snapshot.
---@param versionId string
---@param assets table<string, string|love.Data>|nil fixture payloads by logical generated path
---@return GeneratedCacheFixture.ResidentView
function GeneratedCacheFixture.resident(versionId, assets)
  local sourceId = "base:" .. versionId
  local paths = {}
  for path in pairs(assets or {}) do
    paths[#paths + 1] = path
  end
  table.sort(paths)
  local batch = {}
  local payloads = assets or {}
  for position, path in ipairs(paths) do
    batch[position] = entry(path, payloads[path], sourceId, versionId .. "\0" .. path)
  end
  return residentView(versionId, sourceId, batch)
end

-- Replace or add one payload of a fixture resident view, the way a producer
-- replaces one committed artifact: the new bytes are committed with their own
-- content identity, so a reader keyed by content never serves the old payload.
---@param view GeneratedCacheFixture.ResidentView
---@param path string
---@param bytes string|love.Data
function GeneratedCacheFixture.put(view, path, bytes)
  local serial = (view.serialize or 0) + 1
  view.serialize = serial
  local store = view.store
  store:commit(store:prepare({
    entry(path, bytes, store:sourceId(), view.versionId .. "\0fixture\0" .. path .. "\0" .. serial),
  }))
end

-- A resident view over a fixture cache root a suite has just staged: the
-- fixture's own generated payloads become one resident store, so a consumer
-- that resolves immutable references reads them exactly like installed bytes.
---@param cacheFs table<string, unknown> physical fixture cache root
---@return GeneratedCacheFixture.ResidentView
function GeneratedCacheFixture.fromCache(cacheFs)
  local assets = {}
  local function collect(relative)
    for _, name in ipairs(cacheFs:getDirectoryItems(relative)) do
      local child = relative == "" and name or relative .. "/" .. name
      local info = cacheFs:getInfo(child)
      if info ~= nil and info.type == "directory" then
        collect(child)
      elseif info ~= nil then
        assets[child] = assert(cacheFs:read(child), "a staged fixture payload must be readable: " .. child)
      end
    end
  end
  collect("")
  return GeneratedCacheFixture.resident(assert(cacheFs.versionId, "a fixture cache root names its version"), assets)
end

-- Retire a fixture resident view. Nothing physical was created, so this only
-- drops the fixture's own index; already borrowed buffers stay readable.
---@param view GeneratedCacheFixture.ResidentView
function GeneratedCacheFixture.close(view)
  view.store:close()
end

---@param versionId string
---@return GeneratedCacheFixture.View
function GeneratedCacheFixture.view(versionId)
  assert(type(versionId) == "string" and versionId ~= "", "a generated view needs its version id")
  local view = views[versionId]
  if view == nil then
    view = build(versionId)
    views[versionId] = view
  end
  return view
end

-- Whether this process can serve a version's installed generated view at all.
-- The runner prepares exactly the selected source for its invocation, so a
-- version whose source is still bound but unprepared has no snapshot and no
-- resident bytes; a suite that reads generated output can only iterate the
-- prepared ones.
---@param versionId string
---@return boolean prepared
function GeneratedCacheFixture.isPrepared(versionId)
  if views[versionId] ~= nil then
    return true
  end
  return CacheArchive.recoverableFileName(versionId) ~= nil
end

---@param versionId string
---@return CacheFs installed generated reader
function GeneratedCacheFixture.reader(versionId)
  return GeneratedCacheFixture.view(versionId).reader
end

---@param versionId string
---@return ResidentCache installed byte store
function GeneratedCacheFixture.store(versionId)
  return GeneratedCacheFixture.view(versionId).store
end

---@param versionId string
---@return table<string, unknown> hydrated snapshot
function GeneratedCacheFixture.candidate(versionId)
  return GeneratedCacheFixture.view(versionId).candidate
end

return GeneratedCacheFixture
